/**
 * Unpadded base64url (RFC 4648 §5) -- the encoding JWS uses for every segment.
 */

const ALPHABET = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_';

const REVERSE = (() => {
  const table = new Int16Array(128).fill(-1);
  for (let i = 0; i < ALPHABET.length; i++) table[ALPHABET.charCodeAt(i)] = i;
  // Accept the standard alphabet too, so tokens produced elsewhere still decode.
  table['+'.charCodeAt(0)] = 62;
  table['/'.charCodeAt(0)] = 63;
  return table;
})();

/**
 * @param {Uint8Array} bytes
 * @returns {string} base64url text with the `=` padding stripped
 */
export function b64urlEncode(bytes) {
  let out = '';
  let i = 0;

  for (; i + 2 < bytes.length; i += 3) {
    const n = (bytes[i] << 16) | (bytes[i + 1] << 8) | bytes[i + 2];
    out += ALPHABET[(n >> 18) & 63] + ALPHABET[(n >> 12) & 63] + ALPHABET[(n >> 6) & 63] + ALPHABET[n & 63];
  }

  const rest = bytes.length - i;
  if (rest === 1) {
    const n = bytes[i] << 16;
    out += ALPHABET[(n >> 18) & 63] + ALPHABET[(n >> 12) & 63];
  } else if (rest === 2) {
    const n = (bytes[i] << 16) | (bytes[i + 1] << 8);
    out += ALPHABET[(n >> 18) & 63] + ALPHABET[(n >> 12) & 63] + ALPHABET[(n >> 6) & 63];
  }

  return out;
}

/**
 * @param {string} text base64url text, with or without `=` padding
 * @returns {Uint8Array}
 * @throws {Error} on characters outside the alphabet or an impossible length
 */
export function b64urlDecode(text) {
  let clean = '';
  for (let i = 0; i < text.length; i++) {
    const ch = text[i];
    if (ch === '=') continue;
    const code = text.charCodeAt(i);
    if (code > 127 || REVERSE[code] === -1) {
      throw new Error(`Invalid base64url character: ${JSON.stringify(ch)}`);
    }
    clean += ch;
  }

  if (clean.length % 4 === 1) throw new Error('Invalid base64url length');

  const outLength = Math.floor((clean.length * 3) / 4);
  const out = new Uint8Array(outLength);

  let acc = 0;
  let bits = 0;
  let pos = 0;
  for (let i = 0; i < clean.length; i++) {
    acc = (acc << 6) | REVERSE[clean.charCodeAt(i)];
    bits += 6;
    if (bits >= 8) {
      bits -= 8;
      out[pos++] = (acc >> bits) & 0xff;
    }
  }

  return out;
}

