/**
 * Unicode printability, matching CPython's `str.isprintable()`.
 *
 * CPython defines non-printable as "characters defined in the Unicode character
 * database as Other or Separator, excepting the ASCII space (0x20)". The engine
 * already ships the character database behind regular-expression property
 * escapes, so the categories can be queried directly instead of shipping a
 * table.
 */

const NON_PRINTABLE = /[\p{Cc}\p{Cf}\p{Cs}\p{Co}\p{Cn}\p{Zs}\p{Zl}\p{Zp}]/u;

/** Memo for the BMP; astral code points are rare enough to test on demand. */
const bmpCache = new Int8Array(0x10000).fill(-1);

/**
 * @param {number} codePoint
 * @returns {boolean} true when CPython's `repr()` would emit the character raw
 */
export function isPrintableCodePoint(codePoint) {
  // The ASCII space is the one Separator CPython still calls printable.
  if (codePoint === 0x20) return true;

  if (codePoint < 0x10000) {
    const cached = bmpCache[codePoint];
    if (cached !== -1) return cached === 1;
    const printable = !NON_PRINTABLE.test(String.fromCharCode(codePoint));
    bmpCache[codePoint] = printable ? 1 : 0;
    return printable;
  }

  return !NON_PRINTABLE.test(String.fromCodePoint(codePoint));
}

/**
 * Iterate a JavaScript string by Unicode code point, the way CPython iterates
 * a `str`. Unpaired surrogates are yielded as their own code point.
 *
 * @param {string} str
 * @returns {Generator<number>}
 */
export function* codePoints(str) {
  for (let i = 0; i < str.length; i++) {
    const unit = str.charCodeAt(i);
    if (unit >= 0xd800 && unit <= 0xdbff && i + 1 < str.length) {
      const next = str.charCodeAt(i + 1);
      if (next >= 0xdc00 && next <= 0xdfff) {
        yield (unit - 0xd800) * 0x400 + (next - 0xdc00) + 0x10000;
        i++;
        continue;
      }
    }
    yield unit;
  }
}

