 * `dict`. Objects become `Map`s so that the subsequent `repr()` rendering lists
 * keys in the order they appeared in the document.
 */

class Parser {
  /** @param {string} text */
  constructor(text) {
    this.text = text;
    this.pos = 0;
  }

  error(message) {
    return new SyntaxError(`${message} (char ${this.pos})`);
  }

  skipWhitespace() {
    while (this.pos < this.text.length) {
      const ch = this.text[this.pos];
      if (ch === ' ' || ch === '\t' || ch === '\n' || ch === '\r') this.pos++;
      else break;
    }
  }

  parse() {
    this.skipWhitespace();
    const value = this.parseValue();
    this.skipWhitespace();
    if (this.pos !== this.text.length) throw this.error('Extra data');
    return value;
  }

  parseValue() {
    if (this.pos >= this.text.length) throw this.error('Expecting value');
    const ch = this.text[this.pos];

    if (ch === '{') return this.parseObject();
    if (ch === '[') return this.parseArray();
    if (ch === '"') return this.parseString();

    if (this.text.startsWith('true', this.pos)) {
      this.pos += 4;
      return true;
    }
    if (this.text.startsWith('false', this.pos)) {
      this.pos += 5;
      return false;
    }
    if (this.text.startsWith('null', this.pos)) {
      this.pos += 4;
      return null;
    }

    return this.parseNumber();
  }

  parseObject() {
    const result = new Map();
    this.pos++; // '{'
    this.skipWhitespace();

    if (this.text[this.pos] === '}') {
      this.pos++;
      return result;
    }

    for (;;) {
      this.skipWhitespace();
      if (this.text[this.pos] !== '"') throw this.error('Expecting property name enclosed in double quotes');
      const key = this.parseString();
      this.skipWhitespace();
      if (this.text[this.pos] !== ':') throw this.error("Expecting ':' delimiter");
      this.pos++;
      this.skipWhitespace();
      result.set(key, this.parseValue());
      this.skipWhitespace();

      const ch = this.text[this.pos];
      if (ch === ',') {
        this.pos++;
        continue;
      }
      if (ch === '}') {
        this.pos++;
        return result;
      }
      throw this.error("Expecting ',' delimiter");
    }
  }

  parseArray() {
    const result = [];
    this.pos++; // '['
    this.skipWhitespace();

    if (this.text[this.pos] === ']') {
      this.pos++;
      return result;
    }

    for (;;) {
      this.skipWhitespace();
      result.push(this.parseValue());
      this.skipWhitespace();

      const ch = this.text[this.pos];
      if (ch === ',') {
        this.pos++;
        continue;
      }
      if (ch === ']') {
        this.pos++;
        return result;
      }
      throw this.error("Expecting ',' delimiter");
    }
  }

  parseString() {
    this.pos++; // opening quote
    let out = '';

    for (;;) {
      if (this.pos >= this.text.length) throw this.error('Unterminated string');
      const ch = this.text[this.pos];

      if (ch === '"') {
        this.pos++;
        return out;
      }

      if (ch !== '\\') {
        out += ch;
        this.pos++;
        continue;
      }

      this.pos++;
