    } else if (isPrintableCodePoint(cp)) {
      out += ch;
    } else if (cp < 0x100) {
      out += '\\x' + cp.toString(16).padStart(2, '0');
    } else if (cp < 0x10000) {
      out += '\\u' + cp.toString(16).padStart(4, '0');
    } else {
      out += '\\U' + cp.toString(16).padStart(8, '0');
    }
  }

  return out + quote;
}

/**
 * Render any supported value the way CPython's `repr()` would.
 *
 * @param {unknown} value `Map` renders as a dict, `Array` as a list
 * @returns {string}
 */
export function repr(value) {
  if (value === null || value === undefined) return 'None';

  if (typeof value === 'string') return reprString(value);

  if (typeof value === 'boolean') return value ? 'True' : 'False';

  if (typeof value === 'number') return reprNumber(value);

  if (typeof value === 'bigint') return value.toString();

  if (Array.isArray(value)) return '[' + value.map(repr).join(', ') + ']';

  if (value instanceof Map) {
    const parts = [];
    for (const [key, item] of value) parts.push(`${repr(key)}: ${repr(item)}`);
    return '{' + parts.join(', ') + '}';
  }

  if (typeof value === 'object') {
    const parts = [];
    for (const key of Object.keys(value)) parts.push(`${repr(key)}: ${repr(value[key])}`);
    return '{' + parts.join(', ') + '}';
  }

  return String(value);
}

/**
 * Python distinguishes `int` from `float`; the closest JavaScript can get is to
 * treat whole numbers as ints and give everything else a `.0`-preserving form.
 *
 * @param {number} value
 * @returns {string}
 */
function reprNumber(value) {
  if (Number.isNaN(value)) return 'nan';
  if (value === Infinity) return 'inf';
  if (value === -Infinity) return '-inf';
  return String(value);
}

