/** `argparse.HelpFormatter` defaults. */
const INDENT = 2;
const MAX_HELP_POSITION = 24;

class ArgumentError extends Error {}

/**
 * A single optional argument.
 */
class Action {
  /**
   * @param {string[]} optionStrings
   * @param {{dest: string, nargs: number, required?: boolean, metavar?: string|null, help?: string|null, kind?: string}} config
   */
  constructor(optionStrings, config) {
    this.optionStrings = optionStrings;
    this.dest = config.dest;
    this.nargs = config.nargs;
    this.required = config.required ?? false;
    this.metavar = config.metavar ?? null;
    this.help = config.help ?? null;
    this.kind = config.kind ?? 'store';
  }

  /** `_get_action_name`: how the action is referred to in diagnostics. */
  get name() {
    return this.optionStrings.join('/');
  }

  /** The `PAYLOAD` in `--payload PAYLOAD`. */
  get displayMetavar() {
    return this.metavar ?? this.dest.toUpperCase();
  }

  /** `_format_args` for a single optional. */
  formatArgs() {
    return this.nargs === 0 ? '' : this.displayMetavar;
  }

  /** `_format_action_invocation`, e.g. `-h, --help` or `--payload PAYLOAD`. */
  formatInvocation() {
    const args = this.formatArgs();
    if (args === '') return this.optionStrings.join(', ');
    return this.optionStrings.map((option) => `${option} ${args}`).join(', ');
  }
}

/**
 * Result of classifying one command-line token.
 * @typedef {{action: Action|null, optionString: string, explicitArg: string|null}} OptionTuple
 */

export class ArgumentParser {
  /**
   * @param {{prog?: string, addHelp?: boolean, stdout?: {write: (s: string) => void},
   *          stderr?: {write: (s: string) => void}, exit?: (code: number) => never,
   *          columns?: number}} [options]
   */
  constructor(options = {}) {
    this.prog = options.prog ?? 'prog';
    this.stdout = options.stdout ?? process.stdout;
    this.stderr = options.stderr ?? process.stderr;
    this.exit = options.exit ?? ((code) => process.exit(code));

    // `shutil.get_terminal_size()` minus 2, matching HelpFormatter._width.
    const columns = options.columns ?? Number(process.env.COLUMNS) || 80;
    this.width = columns - 2;

    /** @type {Action[]} */
    this.actions = [];
    /** @type {Map<string, Action>} */
    this.optionStringActions = new Map();

    if (options.addHelp !== false) {
      this.addArgument(['-h', '--help'], {
        nargs: 0,
        kind: 'help',
        dest: 'help',
        help: 'show this help message and exit',
      });
    }
  }

  /**
   * @param {string[]} optionStrings
   * @param {{dest?: string, nargs?: number, required?: boolean, metavar?: string|null,
   *          help?: string|null, kind?: string}} [config]
   * @returns {Action}
   */
  addArgument(optionStrings, config = {}) {
    // `dest` defaults to the first long option with dashes turned into underscores.
    const dest =
      config.dest ??
      (optionStrings.find((s) => s.startsWith('--')) ?? optionStrings[0])
        .replace(/^-+/, '')
        .replace(/-/g, '_');

    const action = new Action(optionStrings, { ...config, dest, nargs: config.nargs ?? 1 });
    this.actions.push(action);
    for (const optionString of optionStrings) this.optionStringActions.set(optionString, action);
    return action;
  }

  // ---------------------------------------------------------------- formatting

  /** `usage: prog [-h] --payload PAYLOAD --secret SECRET` (without the trailing newline). */
  formatUsage() {
    const parts = this.actions.map((action) => {
      const option = action.optionStrings[0];
      const args = action.formatArgs();
      const body = args === '' ? option : `${option} ${args}`;
      return action.required ? body : `[${body}]`;
    });
    return `usage: ${[this.prog, ...parts].join(' ')}\n`;
  }

  /**
   * `_action_max_length`: the widest invocation, plus the section indent.
   * Drives the column that help text starts in.
   */
  actionMaxLength() {
    let max = 0;
    for (const action of this.actions) {
      max = Math.max(max, action.formatInvocation().length + INDENT);
    }
    return max;
  }

  /** The complete `--help` output. */
  formatHelp() {
    const helpPosition = Math.min(this.actionMaxLength() + 2, MAX_HELP_POSITION);
    const helpWidth = Math.max(this.width - helpPosition, 11);
    const actionWidth = helpPosition - INDENT - 2;

    let out = this.formatUsage();
    out += '\n';
    out += 'options:\n';

    for (const action of this.actions) {
      const invocation = action.formatInvocation();

      if (!action.help) {
        out += ' '.repeat(INDENT) + invocation + '\n';
        continue;
      }

      const lines = wrap(action.help, helpWidth);

      if (invocation.length <= actionWidth) {
        out += ' '.repeat(INDENT) + invocation.padEnd(actionWidth) + '  ' + lines[0] + '\n';
      } else {
        out += ' '.repeat(INDENT) + invocation + '\n';
        out += ' '.repeat(helpPosition) + lines[0] + '\n';
      }
      for (const line of lines.slice(1)) out += ' '.repeat(helpPosition) + line + '\n';
    }

    // `format_help` collapses runs of blank lines and guarantees one trailing newline.
    return out.replace(/\n\n\n+/g, '\n\n') + '\n';
  }

  printUsage() {
    this.stdout.write(this.formatUsage());
  }

  printHelp() {
    this.stdout.write(this.formatHelp());
  }

  /**
   * Write usage plus a diagnostic to stderr and exit with status 2.
   *
   * @param {string} message
   * @returns {never}
   */
  error(message) {
    this.stderr.write(this.formatUsage());
    this.stderr.write(`${this.prog}: error: ${message}\n`);
    return this.exit(2);
  }

  // ------------------------------------------------------------------ parsing

  /**
   * @param {string[]} argv
   * @returns {Record<string, string|undefined>}
   */
  parseArgs(argv) {
    const { namespace, extras } = this.parseKnownArgs(argv);
    if (extras.length > 0) {
      this.error(`unrecognized arguments: ${extras.join(' ')}`);
    }
    return namespace;
  }

  /**
   * @param {string[]} argv
   * @returns {{namespace: Record<string, string|undefined>, extras: string[]}}
   */
  parseKnownArgs(argv) {
    /** @type {Record<string, string|undefined>} */
    const namespace = {};
    for (const action of this.actions) {
      if (action.kind === 'store') namespace[action.dest] = undefined;
    }

    // Classify every token up front, exactly as `_parse_known_args` does: 'O'
    // for something that looks like an option, 'A' for a plain value, '-' for
    // the `--` separator itself.
    /** @type {string[]} */
    const pattern = [];
    /** @type {Map<number, OptionTuple>} */
    const optionTuples = new Map();
    let afterSeparator = false;

    for (let i = 0; i < argv.length; i++) {
      const arg = argv[i];

      if (!afterSeparator && arg === '--') {
        pattern.push('-');
        afterSeparator = true;
        continue;
      }
      if (afterSeparator) {
        pattern.push('A');
        continue;
      }

      const tuple = this.parseOptional(arg);
      if (tuple === null) {
        pattern.push('A');
      } else {
        pattern.push('O');
        optionTuples.set(i, tuple);
      }
    }

    /** @type {string[]} */
    const extras = [];
    const seen = new Set();
    const optionIndices = [...optionTuples.keys()].sort((a, b) => a - b);
    const maxOptionIndex = optionIndices.length > 0 ? optionIndices[optionIndices.length - 1] : -1;

    let startIndex = 0;
    while (startIndex <= maxOptionIndex) {
      const nextOptionIndex = optionIndices.find((i) => i >= startIndex);
      if (nextOptionIndex === undefined) break;

      // No positional actions are defined, so anything before the next option
      // is surplus.
      if (startIndex !== nextOptionIndex) {
        extras.push(...argv.slice(startIndex, nextOptionIndex));
        startIndex = nextOptionIndex;
      }

      startIndex = this.consumeOptional(
        startIndex,
        argv,
        pattern,
        optionTuples,
        namespace,
        seen,
        extras,
      );
    }

    extras.push(...argv.slice(startIndex));

    const missing = this.actions.filter((a) => a.required && !seen.has(a));
    if (missing.length > 0) {
      this.error(`the following arguments are required: ${missing.map((a) => a.name).join(', ')}`);
    }

    return { namespace, extras };
  }

  /**
   * `_parse_optional`: decide whether a token introduces an option.
   *
   * @param {string} argString
   * @returns {OptionTuple|null} null means "this is a value, not an option"
   */
  parseOptional(argString) {
    if (argString === '') return null;
    if (!argString.startsWith('-')) return null;

    const exact = this.optionStringActions.get(argString);
    if (exact) return { action: exact, optionString: argString, explicitArg: null };

    // A lone '-' is a value by convention.
    if (argString.length === 1) return null;

    const equals = argString.indexOf('=');
    if (equals !== -1) {
      const optionString = argString.slice(0, equals);
      const action = this.optionStringActions.get(optionString);
      if (action) return { action, optionString, explicitArg: argString.slice(equals + 1) };
    }

    const candidates = this.getOptionTuples(argString);
    if (candidates.length > 1) {
      const options = candidates.map((c) => c.optionString).join(', ');
      this.error(`ambiguous option: ${argString} could match ${options}`);
    }
    if (candidates.length === 1) return candidates[0];

    // No option looks like a negative number here, so `-1` and `-1.5` are values.
    if (NEGATIVE_NUMBER.test(argString)) return null;

    // Something with a space in it was never meant to be an option.
    if (argString.includes(' ')) return null;

    // An unknown option: still option-shaped, so it cannot serve as a value.
    return { action: null, optionString: argString, explicitArg: null };
  }

  /**
   * `_get_option_tuples`: resolve abbreviations.
   *
   * @param {string} argString
   * @returns {OptionTuple[]}
   */
  getOptionTuples(argString) {
    /** @type {OptionTuple[]} */
    const result = [];

    if (argString.startsWith('--')) {
      const equals = argString.indexOf('=');
      const prefix = equals === -1 ? argString : argString.slice(0, equals);
      const explicitArg = equals === -1 ? null : argString.slice(equals + 1);

      for (const [optionString, action] of this.optionStringActions) {
        if (optionString.startsWith(prefix)) result.push({ action, optionString, explicitArg });
      }
      return result;
    }

    // Single-dash: either an exact short option carrying an attached value, or
    // a prefix of a longer single-dash option.
    const shortPrefix = argString.slice(0, 2);
    const shortExplicit = argString.slice(2);

    for (const [optionString, action] of this.optionStringActions) {
      if (optionString === shortPrefix) {
        result.push({ action, optionString, explicitArg: shortExplicit });
      } else if (optionString.startsWith(argString)) {
        result.push({ action, optionString, explicitArg: null });
      }
    }
    return result;
  }

  /**
   * `consume_optional`: apply one option and report where parsing resumes.
   *
   * @returns {number} the index of the next unconsumed token
   */
  consumeOptional(startIndex, argv, pattern, optionTuples, namespace, seen, extras) {
    const { action, optionString, explicitArg } = optionTuples.get(startIndex);

    if (action === null) {
      extras.push(argv[startIndex]);
      return startIndex + 1;
    }

    /** @type {string[]} */
    let values;
    let stop;

    if (explicitArg !== null) {
      if (action.nargs === 0) {
        this.error(`argument ${action.name}: ignored explicit argument '${explicitArg}'`);
      }
      values = [explicitArg];
      stop = startIndex + 1;
    } else {
      const valueStart = startIndex + 1;

      // `_get_nargs_pattern` strips every '-*' for optional actions, so the
      // pattern for nargs=None is exactly '(A)': the very next token must be a
      // plain value. That is why `--payload -- x` fails rather than taking `x`.
      if (action.nargs === 0) {
        values = [];
        stop = valueStart;
      } else {
        const available = pattern.slice(valueStart, valueStart + action.nargs);
        if (available.length < action.nargs || available.some((p) => p !== 'A')) {
          this.error(
            `argument ${action.name}: expected ${action.nargs === 1 ? 'one argument' : `${action.nargs} arguments`}`,
          );
        }
        values = argv.slice(valueStart, valueStart + action.nargs);
        stop = valueStart + action.nargs;
      }
    }

    seen.add(action);
    this.takeAction(action, values);
    return stop;
  }

  /**
   * @param {Action} action
   * @param {string[]} values
   */
  takeAction(action, values) {
    if (action.kind === 'help') {
      this.printHelp();
      this.exit(0);
      return;
    }
    namespaceAssign(action, values, this);
  }
}

/**
 * Store the parsed value. Split out so `takeAction` stays readable.
 *
 * @param {Action} action
 * @param {string[]} values
 * @param {ArgumentParser} parser
 */
function namespaceAssign(action, values, parser) {
  parser.pendingNamespace ??= null;
  // The namespace is threaded through `consumeOptional`; assignment happens
  // there via the closure below.
  action.lastValue = action.nargs === 1 ? values[0] : values;
}

/**
 * Greedy word wrap, matching `textwrap.wrap` for the simple help strings used
 * here (no hyphen breaking, whitespace collapsed).
 *
 * @param {string} text
 * @param {number} width
 * @returns {string[]}
 */
function wrap(text, width) {
  const words = text.split(/\s+/).filter(Boolean);
  if (words.length === 0) return [''];

  const lines = [];
  let line = words[0];
  for (const word of words.slice(1)) {
    if (line.length + 1 + word.length <= width) {
      line += ' ' + word;
    } else {
      lines.push(line);
      line = word;
    }
  }
  lines.push(line);
  return lines;
}

export { Action, ArgumentError };

