export function encodeHeader(algorithm, additionalHeaders = null) {
  const header = new Map([
    ['typ', 'JWT'],
    ['alg', algorithm],
  ]);

  if (additionalHeaders) {
    for (const [key, value] of additionalHeaders) header.set(key, value);
  }

  const sorted = new Map([...header.entries()].sort(([a], [b]) => (a < b ? -1 : a > b ? 1 : 0)));
  return b64urlEncode(utf8Encode(dumps(sorted)));
}

/**
 * @param {Map<string, unknown>} payload
 * @returns {string} the base64url-encoded claims
 */
export function encodePayload(payload) {
  return b64urlEncode(utf8Encode(dumps(payload)));
}

/**
 * Produce a compact JWS.
 *
 * @param {Map<string, unknown>} payload
 * @param {string|Uint8Array} key
 * @param {{headers?: Map<string, unknown>|null, algorithm?: string}} [options]
 * @returns {string}
 */
export function sign(payload, key, options = {}) {
  const algorithm = options.algorithm ?? ALGORITHMS.HS256;

  const hmac = HMAC_FUNCTIONS.get(algorithm);
  if (!hmac) throw new JWSError(`Algorithm ${algorithm} not supported.`);

  const encodedHeader = encodeHeader(algorithm, options.headers ?? null);
  const encodedPayload = encodePayload(payload);

  const signingInput = utf8Encode(`${encodedHeader}.${encodedPayload}`);
  const keyBytes = typeof key === 'string' ? utf8Encode(key) : key;
  const signature = hmac(keyBytes, signingInput);

  return `${encodedHeader}.${encodedPayload}.${b64urlEncode(signature)}`;
}

/**
 * Split a compact token into its three segments.
 *
 * @param {string} token
 * @returns {[string, string, string]}
 */
function splitToken(token) {
  const parts = token.split('.');
  if (parts.length !== 3) throw new JWSError('Not enough segments');
  return /** @type {[string, string, string]} */ (parts);
}

/**
 * Decode a segment without checking the signature.
 *
 * @param {string} segment
 * @param {string} label used in the error message
 * @returns {Uint8Array}
 */
function decodeSegment(segment, label) {
  try {
    return b64urlDecode(segment);
  } catch {
    throw new JWSError(`Invalid ${label} string: ${segment}`);
  }
}

/**
 * @param {string} token
 * @returns {Map<string, unknown>} the header claims, in wire order
 */
export function getUnverifiedHeaders(token) {
  const [headerSegment] = splitToken(token);
  const raw = decodeSegment(headerSegment, 'header');
  try {
    const headers = loads(utf8Decode(raw));
    if (!(headers instanceof Map)) throw new Error('not an object');
    return headers;
  } catch {
    throw new JWSError('Invalid header string: must be a json object');
  }
}

/**
 * @param {string} token
 * @returns {Uint8Array} the raw claims segment
 */
export function getUnverifiedClaims(token) {
  const [, claimsSegment] = splitToken(token);
  return decodeSegment(claimsSegment, 'payload');
}

export { concatBytes };

