import { utf8Decode } from '../binary/bytes.mjs';
import { loads } from '../python/jsonDecoder.mjs';
import { JWTError, JWSError } from './exceptions.mjs';
import {
  ALGORITHMS,
  getUnverifiedClaims as jwsGetUnverifiedClaims,
  getUnverifiedHeaders,
  sign,
} from './jws.mjs';

export { ALGORITHMS };

/**
 * `jwt.encode(claims, key, algorithm='HS256')`.
 *
 * @param {Map<string, unknown>} claims
 * @param {string|Uint8Array} key
 * @param {string} [algorithm]
 * @param {Map<string, unknown>|null} [headers]
 * @returns {string} the compact JWT
 */
export function encode(claims, key, algorithm = ALGORITHMS.HS256, headers = null) {
  return sign(claims, key, { algorithm, headers });
}

