 * check at all.
 *
 * @param {string} token
 * @returns {Map<string, unknown>}
 */
export function getUnverifiedClaims(token) {
  let raw;
  try {
    raw = jwsGetUnverifiedClaims(token);
  } catch (err) {
    if (err instanceof JWSError) throw new JWTError(err.message);
    throw err;
  }

  try {
    return loads(utf8Decode(raw));
  } catch (err) {
    throw new JWTError(`Invalid payload string: ${err.message}`);
  }
}

