 * check at all.
 *
 * @param {string} token
 * @returns {Map<string, unknown>}
 */
export function getUnverifiedHeader(token) {
  try {
    return getUnverifiedHeaders(token);
  } catch (err) {
    if (err instanceof JWSError) throw new JWTError(err.message);
    throw err;
  }
}

