#!/usr/bin/env node
/**
 * Emit the differential corpus as JSON on stdout: an array of argv arrays.
 *
 * The corpus targets the three places the port could realistically drift from
 * the reference: argparse's token classification, SHA-256/HMAC block-boundary
 * padding, and CPython's repr/JSON escaping of awkward code points.
 */

/** @type {string[][]} */
const cases = [];
const push = (...argv) => cases.push(argv);

// ---------------------------------------------------------------- happy path
for (const n of [14, 7, 13, 10, 0, 1, 2, 3, 99]) {
  push('--payload', `unverified_data_${n}`, '--secret', `unverified_secret_${n}`);
}

// ------------------------------------------------------------ argparse surface
push();
push('--payload', 'a');
push('--secret', 'b');
push('--help');
push('-h');
push('-h', '--payload', 'a');
push('--payload', 'a', '-h');
push('--payload', 'a', '--secret', 'b', '--bogus', 'c');
push('--payload');
push('--secret');
push('--payload', 'a', '--secret');
push('--payload', '-x', '--secret', 's');
push('--payload', '--', '--secret', 's');
push('--', '--payload', 'a', '--secret', 's');
push('--payload', 'a', '--secret', 's', '--');
push('--payload', 'a', '--secret', 's', '--', 'extra');
push('--payload', 'a', '--', '--secret', 's');
push('--secret', 's', '--', '--payload', 'a');
push('--payload', '--', 'x', '--secret', 's');
push('--payload', 'a', '--', '--', '--secret', 's');
push('--payload=eq', '--secret=s');
push('--payload=', '--secret=');
push('--payload=a=b', '--secret', 's');
push('--pay', 'abbrev', '--sec', 's');
push('--p', 'x', '--s', 'y');
push('--h');
push('--hel');
push('--help=1');
push('--unknown=1', '--payload', 'a', '--secret', 's');
push('--payload', 'a', '--secret', 'b', '--payload', 'c');
push('--secret', 'a', '--secret', 'b', '--payload', 'c');
push('--payload', '-1', '--secret', 's');
push('--payload', '-1.5', '--secret', 's');
push('--payload', '-.5', '--secret', 's');
push('--payload', '-12345', '--secret', 's');
push('--payload', '-1a', '--secret', 's');
push('--payload', '-', '--secret', 's');
push('--payload', '', '--secret', '');
push('--payload=-x', '--secret', 's');
push('--payload', '-a b', '--secret', 's');
push('--payload', ' -x', '--secret', 's');
push('--payload', 'a', 'b', '--secret', 's');
push('foo', '--payload', 'a', '--secret', 's');
push('-p', 'x', '--payload', 'a', '--secret', 's');
push('-payload', 'x', '--payload', 'a', '--secret', 's');
push('--PAYLOAD', 'x', '--payload', 'a', '--secret', 's');
push('--payloadx', '1', '--payload', 'a', '--secret', 's');
push('---payload', 'a', '--secret', 's');
push('--payload', 'a', '--secret', 's', 'x', 'y', 'z');

// -------------------------------------------- SHA-256 / HMAC length boundaries
const LENGTHS = [
  0, 1, 2, 31, 32, 33, 54, 55, 56, 57, 63, 64, 65, 66, 110, 119, 120, 121, 127, 128, 129, 200, 255,
  1000,
];
for (const n of LENGTHS) {
  push('--payload', 'p'.repeat(n), '--secret', 's');
  push('--payload', 'p', '--secret', 'k'.repeat(n));
}
push('--payload', 'x'.repeat(500), '--secret', 'y'.repeat(500));

// ------------------------------------------------- repr / JSON escaping corpus
/** @type {string[]} */
const specials = [
  // quote selection
  "it's", 'say "hi"', "mix 'a' and \"b\"", "'", '"', '\'"', "''", '""',
  // backslashes and the short escapes
  'a\\b', 'a\\\\b', 'a\tb', 'a\nb', 'a\rb', '\\n', 'ab', 'a b', 'a\bb',
  // C0 controls, DEL, C1 controls
  '', '', '', '', '', '', '', '',
  // separators and format characters
  ' ', '­', '؜', ' ', '᠎', ' ', ' ', ' ',
  '​', '‌', '‍', '‎', '‏', '‪', '‮', '⁠',
  '　', '﻿',
  // private use, replacement, noncharacters, unassigned
  '', '�', '￾', '￿', '퟿', '͸', '׿',
  // printable non-ASCII
  'café', 'ÿ', '你好 wörld', 'こんにちは', 'ᐃᓄᒃ', 'אבגד', 'العربية', 'Ω≈ç√',
  // astral planes
  '😀', '\u{1F1E6}\u{1F1E7}', '\u{2070E}', '\u{10FFFF}', '\u{1D11E}', '\u{E0100}',
  // combining marks and normalization traps
  'é', 'é', 'é̂̃',
  // shell/format-string traps
  'a/b<>&', '%s %d {}', '${HOME}', '`id`', '$(id)', '�'.length ? 'null-free' : '',
  // whitespace shapes
  ' ', '  ', ' a ', ' ', ' ',
];
for (const s of specials) {
  push('--payload', s, '--secret', 's');
  push('--payload', 'p', '--secret', s);
  push('--payload', s, '--secret', s);
}

process.stdout.write(JSON.stringify(cases));

