#!/usr/bin/env node
/**
 * Known-answer tests for the hand-written primitives.
 *
 * SHA-256 vectors are from FIPS 180-4 / the NIST examples; HMAC-SHA256 vectors
 * are RFC 4231 test cases 1-7. Run with: node tools/selftest.mjs
 */

import {
  b64urlDecode,
  b64urlEncode,
  dumps,
  encodeBasestringAscii,
  hmacSha256,
  loads,
  repr,
  sha256,
  toHex,
  utf8Decode,
  utf8Encode,
} from '../lib/index.mjs';

let failures = 0;

/**
 * @param {string} label
 * @param {unknown} actual
 * @param {unknown} expected
 */
function check(label, actual, expected) {
  if (actual === expected) return;
  failures++;
  console.log(`FAIL ${label}\n  expected ${expected}\n  actual   ${actual}`);
}

const bytes = (...values) => Uint8Array.from(values);
const repeat = (byte, count) => new Uint8Array(count).fill(byte);

// ------------------------------------------------------------------- SHA-256
const sha = (text) => toHex(sha256(utf8Encode(text)));

check('sha256("")', sha(''), 'e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855');
check('sha256("abc")', sha('abc'), 'ba7816bf8f01cfea414140de5dae2223b00361a396177a9cb410ff61f20015ad');
check(
  'sha256(56 bytes)',
  sha('abcdbcdecdefdefgefghfghighijhijkijkljklmklmnlmnomnopnopq'),
  '248d6a61d20638b8e5c026930c3e6039a33ce45964ff2167f6ecedd419db06c1',
);
check(
  'sha256(112 bytes)',
  sha(
    'abcdefghbcdefghicdefghijdefghijkefghijklfghijklmghijklmnhijklmno' +
      'ijklmnopjklmnopqklmnopqrlmnopqrsmnopqrstnopqrstu',
  ),
  'cf5b16a778af8380036ce59e7b0492370b249b11e8f07a51afac45037afee9d1',
);
check(
  'sha256(1e6 x "a")',
  sha('a'.repeat(1000000)),
  'cdc76e5c9914fb9281a1c7e284d73e67f1809a48a497200e046d39ccc7112cd0',
);

// --------------------------------------------------------------- HMAC-SHA256
const hmac = (key, message) => toHex(hmacSha256(key, message));

check(
  'rfc4231 tc1',
  hmac(repeat(0x0b, 20), utf8Encode('Hi There')),
  'b0344c61d8db38535ca8afceaf0bf12b881dc200c9833da726e9376c2e32cff7',
);
check(
  'rfc4231 tc2',
  hmac(utf8Encode('Jefe'), utf8Encode('what do ya want for nothing?')),
  '5bdcc146bf60754e6a042426089575c75a003f089d2739839dec58b964ec3843',
);
check(
  'rfc4231 tc3',
  hmac(repeat(0xaa, 20), repeat(0xdd, 50)),
  '773ea91e36800e46854db8ebd09181a72959098b3ef8c122d9635514ced565fe',
);
check(
  'rfc4231 tc4',
  hmac(
    bytes(
      0x01, 0x02, 0x03, 0x04, 0x05, 0x06, 0x07, 0x08, 0x09, 0x0a, 0x0b, 0x0c, 0x0d, 0x0e, 0x0f,
      0x10, 0x11, 0x12, 0x13, 0x14, 0x15, 0x16, 0x17, 0x18, 0x19,
    ),
    repeat(0xcd, 50),
  ),
  '82558a389a443c0ea4cc819899f2083a85f0faa3e578f8077a2e3ff46729665b',
);
check(
  'rfc4231 tc5 (truncated to 128 bits)',
  hmac(repeat(0x0c, 20), utf8Encode('Test With Truncation')).slice(0, 32),
  'a3b6167473100ee06e0c796c2955552b',
);
check(
  'rfc4231 tc6 (131-byte key)',
  hmac(repeat(0xaa, 131), utf8Encode('Test Using Larger Than Block-Size Key - Hash Key First')),
  '60e431591ee0b67f0d8a26aacbf5b77f8e0bc6213728c5140546040f0ee37f54',
);
check(
  'rfc4231 tc7 (131-byte key, long data)',
  hmac(
    repeat(0xaa, 131),
    utf8Encode(
      'This is a test using a larger than block-size key and a larger ' +
        'than block-size data. The key needs to be hashed before being ' +
        'used by the HMAC algorithm.',
    ),
  ),
  '9b09ffa71b942fcb27635fbcd5b0e944bfdc63644f0713938a7f51535c3a35e2',
);

// Boundary cases around HMAC key normalization.
check(
  'hmac empty key',
  hmac(new Uint8Array(0), utf8Encode('')),
  'b613679a0814d9ec772f95d778c35fc5ff1697c493715653c6c712144292c5ad',
);
check(
  'hmac 64-byte key is used verbatim',
  hmac(repeat(0x0b, 64), utf8Encode('x')),
  hmac(repeat(0x0b, 64), utf8Encode('x')),
);
check(
  'hmac 65-byte key is hashed first',
  hmac(repeat(0x0b, 65), utf8Encode('x')),
  hmac(sha256(repeat(0x0b, 65)), utf8Encode('x')),
);

// ------------------------------------------------------------------ base64url
check('b64url empty', b64urlEncode(new Uint8Array(0)), '');
check('b64url 1 byte', b64urlEncode(bytes(0xff)), '_w');
check('b64url 2 bytes', b64urlEncode(bytes(0xff, 0xff)), '__8');
check('b64url 3 bytes', b64urlEncode(bytes(0xff, 0xff, 0xff)), '____');
check('b64url uses - and _', b64urlEncode(bytes(0xfb, 0xff)), '-_8');
for (let n = 0; n <= 40; n++) {
  const original = new Uint8Array(n).map((_, i) => (i * 37 + 11) & 0xff);
  const round = b64urlDecode(b64urlEncode(original));
  check(`b64url round trip n=${n}`, toHex(round), toHex(original));
}

// ----------------------------------------------------------------- UTF-8
for (const text of ['', 'abc', 'café', '你好', '😀', '\u{10FFFF}', 'a�b']) {
  check(`utf8 round trip ${JSON.stringify(text)}`, utf8Decode(utf8Encode(text)), text);
}
check('utf8 astral length', utf8Encode('😀').length, 4);
check('utf8 lone surrogate becomes U+FFFD', utf8Decode(utf8Encode('\ud83d')), '�');

// ------------------------------------------------------- json.dumps behaviour
check('dumps compact separators', dumps(new Map([['a', 1], ['b', 2]])), '{"a":1,"b":2}');
check('dumps ensure_ascii', encodeBasestringAscii('ä'), '"\\u00e4"');
check('dumps surrogate pair', encodeBasestringAscii('😀'), '"\\ud83d\\ude00"');
check('dumps short escapes', encodeBasestringAscii('\b\f\n\r\t"\\'), '"\\b\\f\\n\\r\\t\\"\\\\"');
check('dumps vertical tab is long form', encodeBasestringAscii('\v'), '"\\u000b"');
check('dumps DEL is escaped', encodeBasestringAscii(''), '"\\u007f"');
check('dumps leaves slash alone', encodeBasestringAscii('a/b'), '"a/b"');

// ------------------------------------------------------------- repr behaviour
check('repr plain', repr('abc'), "'abc'");
check('repr single quote inside', repr("it's"), '"it\'s"');
check('repr both quotes', repr('a\'b"c'), '\'a\\\'b"c\'');
check('repr double quote only', repr('say "hi"'), "'say \"hi\"'");
check('repr backslash', repr('a\\b'), "'a\\\\b'");
check('repr tab newline cr', repr('\t\n\r'), "'\\t\\n\\r'");
check('repr vertical tab uses hex', repr('\v'), "'\\x0b'");
check('repr DEL', repr(''), "'\\x7f'");
check('repr nbsp', repr(' '), "'\\xa0'");
check('repr zwnj', repr('‌'), "'\\u200c'");
check('repr astral private use', repr('\u{100000}'), "'\\U00100000'");
check('repr emoji stays raw', repr('😀'), "'😀'");
check('repr dict', repr(new Map([['data', 'x']])), "{'data': 'x'}");
check('repr empty dict', repr(new Map()), '{}');
check('repr nested', repr(new Map([['a', ['b', 1, true, null]]])), "{'a': ['b', 1, True, None]}");

// ------------------------------------------------------------ json round trip
check('loads preserves order', [...loads('{"b":1,"a":2}').keys()].join(','), 'b,a');
check('loads rebuilds astral', loads('"\\ud83d\\ude00"'), '😀');
check('loads escapes', loads('"a\\tb\\u00e4"'), 'a\tbä');

console.log(failures === 0 ? 'all self-tests passed' : `${failures} self-test failure(s)`);
process.exit(failures === 0 ? 0 : 1);

